    match comment.preceding_node() {
        Some(name) if AnyCssDeclarationName::can_cast(name.kind()) => {
            let parent = name.parent();

            // When the declaration name is actually a value inside a component
            // value list, there is no property colon to anchor the comment to,
            // so leave the placement up to the default handling.
            if parent
                .as_ref()
                .is_some_and(|p| p.kind() == CssSyntaxKind::CSS_GENERIC_COMPONENT_VALUE_LIST)
            {
                return CommentPlacement::Default(comment);
            }

            // A comment placed between the property name and the colon should
            // stay attached to the name (e.g. `color /* comment */: value`).
            let is_before_colon = comment
                .following_token()
                .is_some_and(|token| token.kind() == CssSyntaxKind::COLON);

            if is_before_colon {
