    comment: DecoratedComment<CssLanguage>,
) -> CommentPlacement<CssLanguage> {
    let Some(name) = comment.preceding_node() else {
        return CommentPlacement::Default(comment);
    };

    if !AnyCssDeclarationName::can_cast(name.kind()) {
        return CommentPlacement::Default(comment);
    }

    match name.parent() {
        // Comments placed between the property name, the colon, and the value
        // are attached as dangling comments of the enclosing property. The
        // property formatter (`FormatCssGenericProperty`) then prints them
        // relative to the colon: comments before the colon stay next to the
        // name (e.g. `color /* comment */: value`) and comments after the colon
        // stay right after it, with the value moved to the next line
        // (e.g. `color: /* comment */\n  value`).
        Some(parent) if parent.kind() == CssSyntaxKind::CSS_GENERIC_PROPERTY => {
            CommentPlacement::dangling(parent, comment)
        }
        // When the declaration name is actually a value inside a component
        // value list, there is no property colon to anchor the comment to, so
        // leave the placement up to the default handling.
        Some(parent) if parent.kind() == CssSyntaxKind::CSS_GENERIC_COMPONENT_VALUE_LIST => {
            CommentPlacement::Default(comment)
        }
        _ => CommentPlacement::leading(name.clone(), comment),
